// Des: First-run wizard: browser, folder, login, doctor, demo, risk consent
// Flo: login waits for the owner (attended) > setup: lock folder > login > doctor > dry-run demo > record consent only with --yes
// I/O: Ctx (caller) + yes flag + user name > printed steps; consent date saved in the state db; live runs refused without it
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const halt = @import("ru-safe-halt.zig"); const pace = @import("ru-huma-pace.zig"); const priv = @import("ru-safe-priv.zig"); const doct = @import("ru-doct-main.zig"); const disp = @import("ru-jobs-disp.zig");
const CF = .{ .poll = 2000, .minz = 10 };
pub fn loginRun(ctx: *task.Ctx) !void { ctx.page.arm(ctx.conf.brow_time_seco * 1000); try ctx.page.navigate(ctx.aren, ctx.base); task.say(ctx, "log in to Facebook in the browser window (password, QR, 2FA by hand). Waiting...", .{}); const tot = @as(u64, ctx.conf.brow_time_seco) * 5000; var wtd: u64 = 0; while (wtd <= tot) { ctx.page.arm(ctx.conf.brow_time_seco * 1000); const urlz = ctx.page.urlNow(ctx.aren) catch ""; const txt = ctx.page.textNow(ctx.aren) catch ""; if (txt.len >= CF.minz and halt.check(urlz, txt, "") == null) { task.say(ctx, "logged in", .{}); return; } pace.nap(ctx.iozz, CF.poll, ctx.conf.time_scal_perc); wtd += CF.poll; } return error.Timeout; }
fn notice(ctx: *task.Ctx) void { if (std.mem.eql(u8, ctx.conf.lang_main_code, "vi")) { task.say(ctx, "Lưu ý: Facebook không cho phép tự động hóa. Tài khoản của bạn vẫn có thể bị hạn chế dù fb chạy chậm như người thật. Bạn tự chịu rủi ro này.", .{}); task.say(ctx, "Để đồng ý và bật chạy thật, chạy: fb setup --yes", .{}); } else { task.say(ctx, "Note: Facebook does not allow automation. Your account can still be restricted even though fb works at a human pace. You accept this risk.", .{}); task.say(ctx, "To accept and turn on live runs, run: fb setup --yes", .{}); } }
pub fn setupRun(ctx: *task.Ctx, yes: bool, grant: []const u8, dataroot: []const u8) !void { task.say(ctx, "1/5 browser: found and open", .{}); const locked = priv.lockDown(ctx.gpaz, ctx.iozz, dataroot, grant); task.say(ctx, "2/5 data folder: {s} ({s})", .{ dataroot, if (locked) "owner-only" else "permissions not changed" }); task.say(ctx, "3/5 login", .{}); try loginRun(ctx); task.say(ctx, "4/5 doctor", .{}); _ = doct.doctor(ctx, "", "") catch |err| { if (err != error.Drift) return err; task.say(ctx, "some labels were not found: see above, fix labl_over in aa-conf-main.json", .{}); }; task.say(ctx, "5/5 dry-run demo (nothing is posted)", .{}); const prev = ctx.mode; ctx.mode = .dry; defer ctx.mode = prev; disp.exec(ctx, "post", .{ .text = "Hello from fb" }) catch |err| task.say(ctx, "demo note: {s}", .{@errorName(err)}); if (yes) { try ctx.store.metaSet("consent", task.nowMs(ctx)); task.say(ctx, "consent saved: live runs are allowed", .{}); } else if (!task.consentOk(ctx)) notice(ctx) else task.say(ctx, "consent already saved", .{}); }
